"""Integración editorial de los 13 episodios pendientes. Fuentes: ID.md."""
def complete(stories):
 result=[]
 for country,slug,eps,intro,chapters in stories:
  chapters=list(chapters)
  if slug=='estados-unidos':
   eps += [(6,'3FWchjBCagc'),(7,'2oFu3MUe_l0'),(8,'7I5F116nAwA'),(9,'mOMzT7IwqMc'),(10,'P7EBR6HaEH0')]
   intro='De los lagos de Montana al desierto de Arizona, Estados Unidos fue un viaje de contrastes. Yellowstone y los grandes paisajes estaban en el mapa; las personas que me ayudaron y las decisiones frente al calor aparecieron por el camino.'
   chapters[2]=tuple(p.replace(' El resto del recorrido estadounidense necesita todavía su revisión de episodios.','') for p in chapters[2])
   chapters += [
    ('Yellowstone: entre bisontes y tormentas','Después de Red Rock llegué a West Yellowstone. Entrar al parque no significó encontrar carreteras vacías: había tráfico, y un bisonte en la calzada me recordó que allí tocaba ceder el paso. Entre las cascadas, Norris y las tormentas, el paisaje cambiaba a cada rato. Monté la tienda y busqué un lugar cubierto para comer mientras pasaba la lluvia.','Pasé por el cañón de Yellowstone, su lago y Dragon’s Mouth Spring, donde el vapor y el sonido parecían salir de otro mundo. Vi un oso a lo lejos, no tuve un encuentro cercano. Después de Grant Village continué hacia Grand Teton. El viento y los campings llenos complicaron el final del día: no quería pagar una noche que se salía de mi presupuesto, así que seguí agotado. Una pareja me acogió y me dio de comer. Aquello cambió por completo la jornada.'),
    ('Wyoming y Flaming Gorge: aprender a buscar agua','Cerca de Marbleton coincidí con Chris, un cicloviajero alemán que iba hacia el norte. Los bosques fríos iban quedando atrás y aparecían espacios secos, con distancias largas entre servicios. El agua empezó a decidir hasta dónde podía llegar, mucho más que las ganas de avanzar.','En unas instalaciones de mantenimiento de una presa pregunté por agua y acabé pudiendo quedarme, ducharme y reparar el palo de la cámara. Con el calor, el viento y muchos kilómetros vacíos por delante, aceptar aquella pausa tenía sentido. Después llegaron Green River, los tonos rojizos de Flaming Gorge y la entrada en Utah: otro paisaje, otro ritmo.'),
    ('Hacia Moab: cuando continuar exige cambiar el plan','En Vernal, Jaret me recibió a través de Warmshowers y me acompañó en bicicleta al salir. En Rangely apareció otro techo gracias a una persona que trabajaba en el mantenimiento del parque. Eran pequeñas treguas antes de Douglas Pass, donde los ríos secos y las pendientes hicieron la jornada mucho más dura de lo previsto. Una familia me dio agua congelada; en aquel momento era un regalo enorme.','Después de la montaña volví al desierto, pasando por Cisco. Con el calor que estaba soportando, acepté que una pareja me acercara en furgoneta hacia Moab y seguí parte del camino pedaleando. Dormí junto al Colorado, pero el cansancio no desaparecía. En un supermercado conocí a Eva, que me ofreció su casa cerca de Monticello. No todo se resolvía con pedalear más.'),
    ('Monument Valley y los cañones: paisajes y despedidas','El viento me obligó a volver a pedir un traslado parcial antes de llegar a casa de Eva. Me quedé tres días, compartiendo tiempo también con su vecino Adam y sus perros. Ella había viajado en bicicleta por Sudamérica años atrás. Aquellas conversaciones hicieron que despedirse costara más que abandonar muchos de los lugares que llevaba tiempo deseando conocer.','Monument Valley trajo la carretera inmensa entre las formaciones rocosas. Cerca de Oljato encontré ayuda para dormir; por Kayenta coincidí con las celebraciones del 4 de julio. Para visitar Page y Lower Antelope Canyon acepté otro traslado, y después regresé al punto desde el que continuaría la ruta. Más adelante, Teo me acogió en Flagstaff y fui con él al Gran Cañón. Esas visitas forman parte del viaje, aunque no todos sus puntos estén unidos por kilómetros en bicicleta.'),
    ('Arizona y California: la decisión de cuidar el viaje','De Flagstaff bajé por Oak Creek Canyon hacia Sedona. En Cottonwood encontré otra acogida antes de seguir hacia el oeste. Las subidas, un pinchazo y el calor fueron acumulándose. Llegué a Wenden después de una jornada larguísima y ni siquiera la noche me permitió descansar bien: la tienda seguía caliente y una tormenta obligó a cubrirla.','A la mañana siguiente, un conductor que iba hacia San Diego me ofreció llevarme hasta Julian, en California. Acepté. No estaba cruzando América para demostrar que podía aguantar cualquier cosa; quería seguir disfrutando. Allí pude descansar, preparar la entrada en México y retomar caminos hacia Tecate. La última acampada estadounidense quedó cerca de la frontera. Terminaba una etapa dura y generosa a la vez, con mucha más gente en el recuerdo que cifras en el cuentakilómetros.')]
  elif slug=='mexico':
   eps=[(11,'Q6_-zrrmpg8'),(12,'Ynch66iK3Ww'),(13,'LUeVR4pQAzU'),(14,'elinxL1IK6s'),(15,'58ZJz7_6CDE'),(16,'ktwaV1WBnuI'),(17,'DPYQVTFrCnA'),(18,'JTyeN2rJ3tE'),(19,'rAnSVNODPA8')]
   intro='Entré por Tecate y salí hacia Guatemala después de unos tres meses. Entre el desierto, los volcanes y la sierra, México me obligó a improvisar muchas noches; también me abrió casas y conversaciones que terminaron dando sentido al recorrido.'
   chapters=[
    ('Tecate y Baja California: empezar entre amigos','Carlos me esperaba después de la frontera. Los días con él, Yanelli y su perrita Nina fueron una forma amable de entrar en México. Al marcharme, su grupo ciclista me acompañó durante los primeros kilómetros. Venía de escuchar muchas advertencias; aquella bienvenida me permitió empezar a conocer el país a través de personas concretas.','Seguí hacia Ensenada por la Ruta del Vino y encontré cobijo en una estación de bomberos. Después del tráfico de la ciudad, volver a la tierra por algunos tramos de la Baja Divide fue un gusto, aunque también hubo arena, pistas rotas y momentos de empujar. Cerca de San Quintín, una conversación al comprar agua terminó llevándome a casa de Enrique y Pita. Buscaba un lugar para acampar y acabé descansando junto al mar, con una ducha y mi primer mole mexicano.'),
    ('El desierto y el salto a Sinaloa','El restaurante El Sacrificio apareció en medio de una jornada de calor y carretera ondulada. Me quedé con la familia de la propietaria; sombra, agua y conversación bastaban para transformar aquella parada. Al día siguiente seguí entre los grandes cactus y cirios hacia Cataviña. Había belleza, pero también una exigencia física que no convenía ignorar.','Desde Guerrero Negro tomé un autobús hasta La Paz para evitar seguir pedaleando por el calor del sur de la península. Allí esperé el ferry a Mazatlán. Dormí poco durante la travesía y, ya en Sinaloa, los bomberos me dieron un sitio tranquilo para recuperarme. Tras escuchar sus advertencias sobre el tramo hacia Durango, cambié la ruta y continué por la costa. Eran decisiones tomadas con la información de aquel momento, no una valoración permanente sobre la seguridad de una región.','Un río crecido obligó a cruzar en barca hacia Chametla. En una iglesia no pude quedarme y seguí preguntando hasta que una familia me recibió. La desconfianza inicial fue dejando paso a la conversación. Esa mezcla de cautela y hospitalidad también formaba parte de México.'),
    ('Nayarit: una noche entre mangos','Para avanzar utilicé tramos de carretera de peaje cuyo arcén me resultaba más cómodo. Cerca de Tepic, después de una jornada larga, bajé a preguntar en un pueblo dónde podía dormir. Recibí varias negativas. Nadie tenía obligación de alojarme, pero quedaba cada vez menos luz y yo estaba cansado, empapado de sudor y sin un lugar llano donde poner la tienda.','Acabé entrando por un camino entre mangos y montando el campamento casi a oscuras. Una tormenta me despertó cuando ya había conseguido dormirme. No hubo ningún encuentro con jaguares: la inquietud pertenecía a aquella noche y a no saber qué había alrededor. A la mañana siguiente recogí y continué hacia Xalisco, junto a Tepic, donde Paco me había preparado un lugar para descansar.','Después de un par de días, volver a carreteras más pequeñas me acercó a los pueblos. En Tequepexpan pude dormir en el patio de una iglesia gracias a Candelario. Pasé por Jala y seguí entre agaves hacia Tequila, buscando techos para no empezar cada mañana secando la tienda.'),
    ('Guadalajara y Guanajuato: de una valla a una bienvenida','Después de Tequila intenté dormir cerca de Guadalajara. El lugar que había localizado no me pudo alojar y acampé en el bosque. A la mañana siguiente encontré una salida cerrada: tuve que quitar las alforjas y pasar la bicicleta y el equipaje por separado. Bajo la lluvia, aquellos pocos kilómetros se convirtieron en una de las mañanas más agotadoras del viaje.','Guadalajara me dio unos días para descansar, trabajar y pasear. De camino a Guanajuato, otra familia me dejó una casa en construcción para pasar la noche y me ofreció una ducha. Después llegó Billy, que salió a recibirme en bicicleta. En Casa Zúñiga pude contemplar la ciudad desde arriba y conocerla con calma antes de volver a cargar las alforjas.','Salí con Billy durante unos kilómetros y retomé pistas de la Transméxico hacia San Miguel de Allende. Las pendientes y las piedras se hacían notar, pero agradecía estar lejos del tráfico. Al terminar, una mujer me ofreció un espacio donde su marido guardaba herramientas: otro final de jornada que no estaba previsto.'),
    ('Hacia Valle de Bravo: días que también pesan por dentro','No todos los días llevaba el mismo ánimo. La noticia de la muerte de un compañero cicloviajero me dejó sin muchas ganas de pedalear y pasé tiempo leyendo y pensando. Viajar no aparta de lo que ocurre a las personas que conoces; a veces solo te da más silencio para escucharlo.','En Campo Hermoso, Marta me encontró buscando refugio de la lluvia y su familia me dejó una casa en reformas. En Ocampo volví a recibir ayuda para dormir. Seguía hacia los bosques y Valle de Bravo, alternando subidas, neblina y aguaceros. Los santuarios de mariposas que encontré estaban fuera de temporada: no fue una visita para ver la llegada de las monarca.','En Valle de Bravo elegí un alojamiento para descansar antes de la subida hacia el Nevado de Toluca. La montaña me atraía, pero también necesitaba llegar con fuerzas. El día siguiente volvió a terminar buscando un techo cerca del bosque, con frío y la tienda parcialmente protegida de la lluvia.')
   ]+chapters[:2]+[
    ('Puebla y la entrada en Oaxaca: contar también lo incómodo','Después de Paso de Cortés seguí entre pueblos y campos, rodeando Puebla. En Santa Clara encontré cobijo en una sala de una iglesia mientras llovía. Más adelante, las plazas municipales, una invitación a compartir comida y un balneario donde me dejaron pasar la noche fueron haciendo posible avanzar por una sierra que parecía no tener llano.','En un pueblo anterior a Oaxaca viví una situación muy distinta. Según conté en el episodio, un policía empezó a tocar mis alforjas y hacerme preguntas de una manera que me hizo sentir intimidado cuando ya estaba acostado. No grabé el encuentro. Después hablaron conmigo su superior y el alcalde. Fue una noche incómoda y de poco descanso; no la convierto en una acusación general contra un país ni afirmo que hubiera una petición de dinero que el relato no documenta.','Quería contar esa experiencia sin borrar todas las anteriores. Desde Tecate había recibido ayuda de familias, iglesias, bomberos y personas encontradas por casualidad. Lo desagradable también pertenece al viaje, pero no resume todo lo que había vivido.')
   ]+chapters[2:]+[
    ('Chiapas y la despedida de México','Salí de la sierra de Oaxaca con las piernas y la cabeza cansadas. En un pueblo pude dormir en un garaje municipal mientras la lluvia dejaba cortes de luz. Hacia Palomares tuve que cambiar una cámara y agradecí una noche de camping, ducha y descanso antes de volver a las cuestas. No todos los días tenía ganas de afrontar otra subida.','Entre caminos y vegetación vi monos y seguí hacia la presa de Malpaso. Para evitar un tramo de pista muy roto tomé una barca local hasta Raudales de Malpaso. Allí dormí en una cancha, esperando a que terminara la actividad del pueblo. Después encontré acogida en un albergue orientado a ayudar a personas migrantes: lo cuento como la ayuda que recibí, no como un alojamiento turístico.','Antes de salir del país visité San Cristóbal de las Casas. Luego llegó el momento de sellar la salida y subir hacia La Mesilla, donde Jaime me esperaba al otro lado de la frontera. Me despedí agradecido por los mensajes, las recomendaciones y los muchos espacios que me habían abierto. Oaxaca y Chiapas habían sido exigentes; Guatemala empezaba con ganas de escuchar, descansar y descubrir otro país.')]
  elif slug=='guatemala':
   eps += [(22,'6VyxwOtdyPM')]
   chapters[3]=tuple(p.replace(' La continuación hacia la costa queda pendiente de revisar.','') for p in chapters[3])
   chapters += [
    ('De Pacaya al calor de la costa','El viento no me había dejado preparar el desayuno junto al volcán. Bajé hacia Los Pocitos para comer antes de seguir entre cafetales en dirección al Pacífico. Dejaba atrás la altura, pero no las pequeñas subidas ni la necesidad de resolver dónde dormir cada tarde.','Un lugar junto a una laguna que parecía prometedor resultó estar mucho menos preparado de lo que esperaba. Seguí hacia un ecoparque y llegué cansado, con hambre y ya de noche. Finalmente pude quedarme, aunque encontrar un trozo de suelo llano también llevó su esfuerzo. Aquella jornada resumía bien una parte poco visible del viaje: a veces la diferencia entre un buen día y uno difícil es conseguir descansar.'),
    ('La Combi: una pausa antes de la frontera','Cerca de Chiquimulilla encontré La Combi. Javier me recibió con una naturalidad que invitaba a quedarme y conversar. Me contó que había viajado décadas atrás y que quería devolver parte de la ayuda recibida. El proyecto, construido con su mujer, había tomado el nombre de una Volkswagen que le regaló su hijo.','Me interesaba escuchar a quien está al otro lado de esas puertas que se abren a los viajeros. Pasé dos días allí antes de continuar hacia la frontera de Ciudad Pedro de Alvarado. Me despedía de Guatemala agradecido por las personas y los paisajes, aunque algunos tramos de tráfico me habían hecho sentir vulnerable. La entrada en El Salvador fue sencilla en mi caso y el viaje volvió a acercarse al mar.')]
  elif slug=='el-salvador':
   eps=[(22,'6VyxwOtdyPM')]+eps
   chapters=[('Volver al Pacífico','Crucé desde Guatemala después de descansar en La Combi. Javier me había recomendado El Ancla, junto al mar, y allí pude acampar. Después de tantas montañas, volver a escuchar el océano cambió la forma de terminar el día.','Bianca me permitió conocer su trabajo cuidando huevos de tortuga hasta la eclosión. Presencié la liberación de crías al mar, uno de los recuerdos más bonitos de aquella entrada en el país. No estaba en mis planes al cruzar la frontera. Después tocaría volver a subir hacia los volcanes, buscando también algo de frescor.')]+chapters
  result.append((country,slug,eps,intro,chapters))
 return result

SUMMARIES={
 'estados-unidos':['Montana: lagos, primeras acogidas y caminos abiertos.','Yellowstone y Grand Teton entre fauna, tráfico y tormentas.','Wyoming y Flaming Gorge: agua, distancia y refugios inesperados.','Moab, Monument Valley y visitas a los grandes cañones.','El calor de Arizona y los traslados que cambiaron la ruta.','California y los últimos días antes de cruzar por Tecate.'],
 'mexico':['La bienvenida en Tecate y los caminos de Baja California.','El ferry a Sinaloa y las decisiones para continuar la ruta.','Nayarit, Tequila, Guadalajara y Guanajuato entre lluvias y encuentros.','Los bosques, Ciudad de México y Paso de Cortés.','Oaxaca: hospitalidad, una noche incómoda y una sierra exigente.','Chiapas, Malpaso y San Cristóbal antes de entrar en Guatemala.'],
 'guatemala':['La Mesilla, averías y la necesidad de recuperar fuerzas.','Atitlán entre carreteras, cuestas y una travesía en barca.','Antigua y las decisiones para evitar tramos de tráfico.','La subida a Pacaya y una noche expuesta al viento.','El descenso hacia la costa y la búsqueda de un lugar para dormir.','Javier y La Combi antes de cruzar hacia El Salvador.']}
